insert into public.hai_runtime_settings
  (key, label, description, category, value, default_value, value_type, enabled)
values
('image_prompt.compose', '生图总模板', '所有独立生图和图片 PPT 在提交给生图服务前，使用这份模板拼装尺寸、风格与用户要求。', 'image_prompts', '"图片尺寸：{{size}}\n{{subject_line}}视觉风格：{{style_label}}。{{style_prompt}}\n生成图类型：{{image_type}}。\n{{reference_line}}\n用户原始要求：\n{{prompt}}"'::jsonb, '"图片尺寸：{{size}}\n{{subject_line}}视觉风格：{{style_label}}。{{style_prompt}}\n生成图类型：{{image_type}}。\n{{reference_line}}\n用户原始要求：\n{{prompt}}"'::jsonb, 'string', true),
('image_prompt.reference', '参考图修改规则', '上传参考图或沿用上一轮图片时，加入总模板。', 'image_prompts', '"参考图片：按用户要求修改，保留未指定修改的内容。"'::jsonb, '"参考图片：按用户要求修改，保留未指定修改的内容。"'::jsonb, 'string', true),
('image_prompt.style.卡通', '卡通', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用清晰生动的卡通插画，暖白底、蓝绿与橙色有限配色。标题使用端正圆角黑体，正文深灰清晰；人物动作自然、轮廓干净，以本课情境为主体。背景简洁，避免无关贴纸和夸张表情遮挡学习内容。"'::jsonb, '"采用清晰生动的卡通插画，暖白底、蓝绿与橙色有限配色。标题使用端正圆角黑体，正文深灰清晰；人物动作自然、轮廓干净，以本课情境为主体。背景简洁，避免无关贴纸和夸张表情遮挡学习内容。"'::jsonb, 'string', true),
('image_prompt.style.写真', '写真', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用自然写实的摄影视觉，柔和自然光、主体与背景层次清楚，暖白信息区、深灰文字与少量主题强调色。短标题用稳健粗黑体，正文清晰；景物和人物与本课内容、年代及学段相符，避免照片细节干扰文字。"'::jsonb, '"采用自然写实的摄影视觉，柔和自然光、主体与背景层次清楚，暖白信息区、深灰文字与少量主题强调色。短标题用稳健粗黑体，正文清晰；景物和人物与本课内容、年代及学段相符，避免照片细节干扰文字。"'::jsonb, 'string', true),
('image_prompt.style.3D', '3D', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用清楚的三维教学视觉，浅色背景、哑光材质、柔和均匀光照与适度接触阴影。标题用粗黑体，正文深灰，蓝绿和橙色区分对象。主体结构直观、视角便于观察；数量、连接和相对位置依据输入，装饰不遮挡内容。"'::jsonb, '"采用清楚的三维教学视觉，浅色背景、哑光材质、柔和均匀光照与适度接触阴影。标题用粗黑体，正文深灰，蓝绿和橙色区分对象。主体结构直观、视角便于观察；数量、连接和相对位置依据输入，装饰不遮挡内容。"'::jsonb, 'string', true),
('image_prompt.style.教育扁平插画', '教育扁平插画', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用简洁的教育扁平插画，暖白底、蓝绿主色与少量橙色强调，清楚的轮廓、规整图形与有限色块。标题用粗黑体，正文用清晰无衬线字体；主体与本课情境一致，图文分区、对齐留白，不添加无关学科符号。"'::jsonb, '"采用简洁的教育扁平插画，暖白底、蓝绿主色与少量橙色强调，清楚的轮廓、规整图形与有限色块。标题用粗黑体，正文用清晰无衬线字体；主体与本课情境一致，图文分区、对齐留白，不添加无关学科符号。"'::jsonb, 'string', true),
('image_prompt.style.水彩', '水彩', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用柔和水彩笔触与轻微纸张质感，奶油白底、低饱和蓝绿和赭橙。标题使用易辨识宋体气质，正文深灰；水彩渲染主要放在本课主体与边缘，文字区保持干净，避免淡色文字和大面积晕染降低可读性。"'::jsonb, '"采用柔和水彩笔触与轻微纸张质感，奶油白底、低饱和蓝绿和赭橙。标题使用易辨识宋体气质，正文深灰；水彩渲染主要放在本课主体与边缘，文字区保持干净，避免淡色文字和大面积晕染降低可读性。"'::jsonb, 'string', true),
('image_prompt.style.杂志拼贴', '杂志拼贴', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用照片、色块与纸张组成的课堂杂志拼贴，暖白底、墨黑文字与两种有限强调色。短标题用粗黑体，正文清楚；以本课提供的材料组织主图、引文与问题卡，裁切有序，避免随机报纸正文、虚构数据和过密装饰。"'::jsonb, '"采用照片、色块与纸张组成的课堂杂志拼贴，暖白底、墨黑文字与两种有限强调色。短标题用粗黑体，正文清楚；以本课提供的材料组织主图、引文与问题卡，裁切有序，避免随机报纸正文、虚构数据和过密装饰。"'::jsonb, 'string', true),
('image_prompt.style.手绘绘本', '手绘绘本', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用温暖手绘绘本，奶油白底、低饱和蓝绿与杏橙，轻微彩铅或水彩笔触。标题用端正圆角黑体，正文深灰；少量人物构成一个与本课对应的叙事情境，动作表情自然，符合学段，留出清楚的文字区。"'::jsonb, '"采用温暖手绘绘本，奶油白底、低饱和蓝绿与杏橙，轻微彩铅或水彩笔触。标题用端正圆角黑体，正文深灰；少量人物构成一个与本课对应的叙事情境，动作表情自然，符合学段，留出清楚的文字区。"'::jsonb, 'string', true),
('image_prompt.style.国风水墨', '水墨诗境', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用淡雅水墨诗境，米白宣纸底、墨黑文字、少量青灰或朱砂点睛。短标题用舒展而可辨的毛笔字，正文用清晰宋体气质。水墨浓淡、远近层次与大面积留白共同构图，只画本课文本相关的山水、植物、季节和人物意象。封面可以诗意铺陈，内容页的文字区保持干净；不自动添加亭台、竹子、飞鸟或与文本无关的古代人物。"'::jsonb, '"采用淡雅水墨诗境，米白宣纸底、墨黑文字、少量青灰或朱砂点睛。短标题用舒展而可辨的毛笔字，正文用清晰宋体气质。水墨浓淡、远近层次与大面积留白共同构图，只画本课文本相关的山水、植物、季节和人物意象。封面可以诗意铺陈，内容页的文字区保持干净；不自动添加亭台、竹子、飞鸟或与文本无关的古代人物。"'::jsonb, 'string', true),
('image_prompt.style.科技未来', '科技未来', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用克制的科技未来教学视觉，深蓝与青蓝构成封面色调，内容区用浅底和高对比文字。标题粗黑体，主体以清楚的科技结构、线条与空间关系呈现，围绕本课现象；避免无意义代码、霓虹装饰和企业发布会版式。"'::jsonb, '"采用克制的科技未来教学视觉，深蓝与青蓝构成封面色调，内容区用浅底和高对比文字。标题粗黑体，主体以清楚的科技结构、线条与空间关系呈现，围绕本课现象；避免无意义代码、霓虹装饰和企业发布会版式。"'::jsonb, 'string', true),
('image_prompt.style.黏土定格', '黏土定格', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用黏土模型与定格动画质感，暖白底、蓝绿与橙黄有限配色，哑光手工表面和柔和阴影。标题用厚实圆角黑体，正文深灰；人物、景物与物件均使用统一黏土媒介，轮廓清楚，数量与关系严格依据本课输入。"'::jsonb, '"采用黏土模型与定格动画质感，暖白底、蓝绿与橙黄有限配色，哑光手工表面和柔和阴影。标题用厚实圆角黑体，正文深灰；人物、景物与物件均使用统一黏土媒介，轮廓清楚，数量与关系严格依据本课输入。"'::jsonb, 'string', true),
('image_prompt.style.扁平信息图', '扁平信息图', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用清楚的扁平教学信息图，白底、深蓝标题、青绿与橙色分类。标题和正文用清晰无衬线字体，图标简洁、分区对齐、连接线与方向明确。概念、步骤、数据和层级只使用输入内容，不为美观增加节点、数字或关系。"'::jsonb, '"采用清楚的扁平教学信息图，白底、深蓝标题、青绿与橙色分类。标题和正文用清晰无衬线字体，图标简洁、分区对齐、连接线与方向明确。概念、步骤、数据和层级只使用输入内容，不为美观增加节点、数字或关系。"'::jsonb, 'string', true),
('image_prompt.style.黑板粉笔', '黑板粉笔', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用黑板与粉笔笔触的课堂视觉，深绿黑板、暖白文字、少量黄蓝强调。短标题用清晰粉笔手写气质，正文端正，板书层次与线条明确；文字区不铺密集粉尘纹理，只画本课需要的图示。学习单改用白纸与深色粉笔式线条。"'::jsonb, '"采用黑板与粉笔笔触的课堂视觉，深绿黑板、暖白文字、少量黄蓝强调。短标题用清晰粉笔手写气质，正文端正，板书层次与线条明确；文字区不铺密集粉尘纹理，只画本课需要的图示。学习单改用白纸与深色粉笔式线条。"'::jsonb, 'string', true),
('image_prompt.style.纸艺拼贴', '纸艺拼贴', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用剪纸、折纸与纸艺拼贴质感，米白底、有限主题色，清楚的纸层与轻微投影。标题用端正粗黑体，正文深灰；本课主体以统一纸艺构成，边缘有手工感，文字区平整干净，避免过多层次遮挡教学对象。"'::jsonb, '"采用剪纸、折纸与纸艺拼贴质感，米白底、有限主题色，清楚的纸层与轻微投影。标题用端正粗黑体，正文深灰；本课主体以统一纸艺构成，边缘有手工感，文字区平整干净，避免过多层次遮挡教学对象。"'::jsonb, 'string', true),
('image_prompt.style.漫画分镜', '漫画分镜', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用课堂漫画分镜，暖白底、深色清楚线稿、少量蓝橙强调。标题用粗黑体，台词和正文清晰；以少量按顺序排列的画格呈现本课情境，人物外观一致、动作明确，阅读方向清楚，不额外编造台词、结论或夸张对错标签。"'::jsonb, '"采用课堂漫画分镜，暖白底、深色清楚线稿、少量蓝橙强调。标题用粗黑体，台词和正文清晰；以少量按顺序排列的画格呈现本课情境，人物外观一致、动作明确，阅读方向清楚，不额外编造台词、结论或夸张对错标签。"'::jsonb, 'string', true),
('image_prompt.style.红金山河', '红金山河', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用红金山河叙事视觉。深红渐变与暖金形成庄重而有行动感的氛围，以本课相关的真实山河、城乡空间或人物行动为主视觉，摄影与克制的数字合成为主要媒介。短标题用厚实舒展、带轻微飞白的毛笔行书气质，暖金或暖白；正文用清晰黑体。封面让标题与远景构成前后层次，云雾只放边角。内容页用米白信息区与真实场景照片，深红导航、金色少量强调。画面服务于本课情境，不自动加入纪念建筑、演讲舞台或人物名。"'::jsonb, '"采用红金山河叙事视觉。深红渐变与暖金形成庄重而有行动感的氛围，以本课相关的真实山河、城乡空间或人物行动为主视觉，摄影与克制的数字合成为主要媒介。短标题用厚实舒展、带轻微飞白的毛笔行书气质，暖金或暖白；正文用清晰黑体。封面让标题与远景构成前后层次，云雾只放边角。内容页用米白信息区与真实场景照片，深红导航、金色少量强调。画面服务于本课情境，不自动加入纪念建筑、演讲舞台或人物名。"'::jsonb, 'string', true),
('image_prompt.style.红色党建', '红色党建', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用浅底红色党建视觉，以暖白和淡米色为主背景，深红标题与少量平面金色线条突出主题。短标题用厚重端正的黑体气质，必要时使用克制的书法题字；正文墨黑。只选择与本课直接相关的红色文化建筑、历史地点或人物活动，红绸和剪影放在边缘，不挤占内容。整体为简洁平面设计结合写实照片，封面庄重，内容页清爽；避免满屏红金渐变、厚重立体金字和商业汇报排版。"'::jsonb, '"采用浅底红色党建视觉，以暖白和淡米色为主背景，深红标题与少量平面金色线条突出主题。短标题用厚重端正的黑体气质，必要时使用克制的书法题字；正文墨黑。只选择与本课直接相关的红色文化建筑、历史地点或人物活动，红绸和剪影放在边缘，不挤占内容。整体为简洁平面设计结合写实照片，封面庄重，内容页清爽；避免满屏红金渐变、厚重立体金字和商业汇报排版。"'::jsonb, 'string', true),
('image_prompt.style.近代史档案', '近代史档案', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用近代史档案编辑视觉，米白旧纸作背景，炭黑作正文，暗红作年代与重点，少量灰褐照片质感。短标题为厚实宋体或报刊衬线字气质，正文为清晰黑体。依据本课提供的材料组织照片、档案卡、时间轴和简短引文，边缘可有轻微纸纹，不在文字区铺强烈污渍。生成的历史情境只能作为示意，不伪造史料编号、报纸正文、人物肖像或档案出处；服饰、建筑与物件保持在指定年代。"'::jsonb, '"采用近代史档案编辑视觉，米白旧纸作背景，炭黑作正文，暗红作年代与重点，少量灰褐照片质感。短标题为厚实宋体或报刊衬线字气质，正文为清晰黑体。依据本课提供的材料组织照片、档案卡、时间轴和简短引文，边缘可有轻微纸纹，不在文字区铺强烈污渍。生成的历史情境只能作为示意，不伪造史料编号、报纸正文、人物肖像或档案出处；服饰、建筑与物件保持在指定年代。"'::jsonb, 'string', true),
('image_prompt.style.现代法治', '现代法治', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用现代法治与公共生活视觉，暖白底、海军蓝标题、蓝灰分区，朱红仅用于关键提示。标题用稳健的粗黑体，正文用干净的无衬线字体。以本课相关的校园、社区、公共服务或规则情境为主体，简洁人物插画与线性关系图相结合，卡片对齐、留白充分。"'::jsonb, '"采用现代法治与公共生活视觉，暖白底、海军蓝标题、蓝灰分区，朱红仅用于关键提示。标题用稳健的粗黑体，正文用干净的无衬线字体。以本课相关的校园、社区、公共服务或规则情境为主体，简洁人物插画与线性关系图相结合，卡片对齐、留白充分。"'::jsonb, 'string', true),
('image_prompt.style.生活情境', '生活情境', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用温暖而清楚的生活情境插画，暖白底、柔和蓝绿与少量珊瑚橙，人物为自然的学生、家人或社区成员。标题用亲切但端正的圆角黑体，正文保持清晰。通过一幅主体情境或少量顺序分镜表现本课的人物动作和互动，保留观察与讨论空间；人物表情适度，服饰与学段匹配。不要以夸张表情、标签或对错标识提前替学生判断。"'::jsonb, '"采用温暖而清楚的生活情境插画，暖白底、柔和蓝绿与少量珊瑚橙，人物为自然的学生、家人或社区成员。标题用亲切但端正的圆角黑体，正文保持清晰。通过一幅主体情境或少量顺序分镜表现本课的人物动作和互动，保留观察与讨论空间；人物表情适度，服饰与学段匹配。不要以夸张表情、标签或对错标识提前替学生判断。"'::jsonb, 'string', true),
('image_prompt.style.议题杂志', '议题杂志', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用课堂议题杂志视觉，暖白或浅灰底、墨黑大字、深蓝与少量朱红强调。标题为粗黑体，正文用易读无衬线字体，照片、引文和问题卡按规整网格排布。用一张本课相关的现实情境主图引出问题，不用装饰图片代替材料；对比材料平衡呈现，重要问题突出。只展示提供的数据和引文，不制造新闻标题、统计图或结论。"'::jsonb, '"采用课堂议题杂志视觉，暖白或浅灰底、墨黑大字、深蓝与少量朱红强调。标题为粗黑体，正文用易读无衬线字体，照片、引文和问题卡按规整网格排布。用一张本课相关的现实情境主图引出问题，不用装饰图片代替材料；对比材料平衡呈现，重要问题突出。只展示提供的数据和引文，不制造新闻标题、统计图或结论。"'::jsonb, 'string', true),
('image_prompt.style.青绿工笔', '青绿工笔', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用青绿工笔视觉，米绢色浅底、石青石绿为景物主色，赭石与少量平面金色作细节。短标题用端正书法或厚实宋体气质，正文墨黑。主体以细致轮廓、克制设色和清楚的人物或物件结构表现，边缘纹样少量出现。图像围绕本课指定对象，文字区留白；避免水墨大面积糊化、过度金属光泽和不合年代的服装建筑。"'::jsonb, '"采用青绿工笔视觉，米绢色浅底、石青石绿为景物主色，赭石与少量平面金色作细节。短标题用端正书法或厚实宋体气质，正文墨黑。主体以细致轮廓、克制设色和清楚的人物或物件结构表现，边缘纹样少量出现。图像围绕本课指定对象，文字区留白；避免水墨大面积糊化、过度金属光泽和不合年代的服装建筑。"'::jsonb, 'string', true),
('image_prompt.style.园林雅韵', '园林雅韵', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用赭金园林雅韵：米白纸纹为底，赭棕标题带、淡金边线、墨绿景物。短标题用舒展且易辨的毛笔字，正文用清晰黑体或宋体气质。将本课相关的园林、建筑或文化空间作为主视觉，用园窗、屋檐或圆章中的一两种组织画面，云纹仅作轻微边饰。封面可横向铺陈建筑空间，内容页改为浅底观察卡片；不照搬教学比赛导航、参赛团队栏和密集说课指标。"'::jsonb, '"采用赭金园林雅韵：米白纸纹为底，赭棕标题带、淡金边线、墨绿景物。短标题用舒展且易辨的毛笔字，正文用清晰黑体或宋体气质。将本课相关的园林、建筑或文化空间作为主视觉，用园窗、屋檐或圆章中的一两种组织画面，云纹仅作轻微边饰。封面可横向铺陈建筑空间，内容页改为浅底观察卡片；不照搬教学比赛导航、参赛团队栏和密集说课指标。"'::jsonb, 'string', true),
('image_prompt.style.非遗国潮', '非遗国潮', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用朱红青绿非遗视觉，朱红、米金与暖白构成主色，青绿少量点缀。封面短标题为米金毛笔大字，正文墨黑，器物为写实摄影或清楚的写实渲染。让本课指定的工艺器物、纹样或制作动作成为唯一主视觉，使用弧形分区和少量文化边饰。内容页以暖白为底呈现器物局部与简短标注；不要将装饰纹样拼成虚构工艺，不复制参考作者、机构、竞赛标识和课程信息。"'::jsonb, '"采用朱红青绿非遗视觉，朱红、米金与暖白构成主色，青绿少量点缀。封面短标题为米金毛笔大字，正文墨黑，器物为写实摄影或清楚的写实渲染。让本课指定的工艺器物、纹样或制作动作成为唯一主视觉，使用弧形分区和少量文化边饰。内容页以暖白为底呈现器物局部与简短标注；不要将装饰纹样拼成虚构工艺，不复制参考作者、机构、竞赛标识和课程信息。"'::jsonb, 'string', true),
('image_prompt.style.文学与博物馆', '文学与博物馆', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用克制的文学与博物馆编辑视觉，暖白背景、墨黑正文、深棕或蓝灰标题，少量单色强调。短标题使用厚实宋体或衬线字气质，正文清晰，图文形成安静的阅读节奏。以本课提供的文本意象、作品或器物作为主图，按大图、短引文、观察问题组织画面，不自动添加旧纸破损和古风纹样。展示用图与背景保持清楚边界，不虚构作品出处和说明。"'::jsonb, '"采用克制的文学与博物馆编辑视觉，暖白背景、墨黑正文、深棕或蓝灰标题，少量单色强调。短标题使用厚实宋体或衬线字气质，正文清晰，图文形成安静的阅读节奏。以本课提供的文本意象、作品或器物作为主图，按大图、短引文、观察问题组织画面，不自动添加旧纸破损和古风纹样。展示用图与背景保持清楚边界，不虚构作品出处和说明。"'::jsonb, 'string', true),
('image_prompt.style.温暖绘本', '温暖绘本', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用温暖手绘绘本，奶油白背景、低饱和蓝绿和杏橙配色，可见轻微水彩或彩铅笔触。标题用端正圆角黑体气质，正文深灰清晰。以本课相关的少量人物或动物构成一个明确场景，表情自然，动作易读，保留大面积文字空白。细节按学段控制，既有故事感又不拥挤；避免满屏可爱贴纸、婴幼儿化造型和无关吉祥物。"'::jsonb, '"采用温暖手绘绘本，奶油白背景、低饱和蓝绿和杏橙配色，可见轻微水彩或彩铅笔触。标题用端正圆角黑体气质，正文深灰清晰。以本课相关的少量人物或动物构成一个明确场景，表情自然，动作易读，保留大面积文字空白。细节按学段控制，既有故事感又不拥挤；避免满屏可爱贴纸、婴幼儿化造型和无关吉祥物。"'::jsonb, 'string', true),
('image_prompt.style.几何极简', '几何极简', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用几何极简教学视觉，白底、深蓝文字、青绿和橙色区分对象。标题为粗黑体，正文为清楚的无衬线字体，线条均匀、图形整洁、标签与对象对应。主体是本课明确提供的图形、数量或关系，必要的辅助线比主体线浅，不用随机公式和几何符号装饰背景。图形的颜色服务于辨认，不能代替数字与关系标注；不自行补造刻度和结论。"'::jsonb, '"采用几何极简教学视觉，白底、深蓝文字、青绿和橙色区分对象。标题为粗黑体，正文为清楚的无衬线字体，线条均匀、图形整洁、标签与对象对应。主体是本课明确提供的图形、数量或关系，必要的辅助线比主体线浅，不用随机公式和几何符号装饰背景。图形的颜色服务于辨认，不能代替数字与关系标注；不自行补造刻度和结论。"'::jsonb, 'string', true),
('image_prompt.style.操作学具', '操作学具', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用操作学具视觉，暖白背景、蓝黄红有限配色，标题用清晰圆角黑体，正文墨黑。以积木、分数片、计数器或本课指定材料的简洁三维模型为主体，哑光材质、柔和光线、清楚接触阴影，摆放有序。物件数量和组合方式严格依据输入，主视角便于学生看清操作，不用透视遮挡关键部分；不为美观增加或减少学具。"'::jsonb, '"采用操作学具视觉，暖白背景、蓝黄红有限配色，标题用清晰圆角黑体，正文墨黑。以积木、分数片、计数器或本课指定材料的简洁三维模型为主体，哑光材质、柔和光线、清楚接触阴影，摆放有序。物件数量和组合方式严格依据输入，主视角便于学生看清操作，不用透视遮挡关键部分；不为美观增加或减少学具。"'::jsonb, 'string', true),
('image_prompt.style.复古语言课堂', '复古语言课堂', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用复古语言课堂编辑视觉，奶油黄背景、靛蓝和砖红几何边饰、墨黑文字。英文短标题使用厚实衬线字气质，中文标题使用相协调的宋体气质，正文简洁清晰。主图与本课语篇、生活场景或文化内容对应，照片可有轻微暖色处理，边饰局限在外围。所有词句按输入逐字呈现，留出例句和练习区域；不自动铺满字母、伦敦地标或国旗。"'::jsonb, '"采用复古语言课堂编辑视觉，奶油黄背景、靛蓝和砖红几何边饰、墨黑文字。英文短标题使用厚实衬线字气质，中文标题使用相协调的宋体气质，正文简洁清晰。主图与本课语篇、生活场景或文化内容对应，照片可有轻微暖色处理，边饰局限在外围。所有词句按输入逐字呈现，留出例句和练习区域；不自动铺满字母、伦敦地标或国旗。"'::jsonb, 'string', true),
('image_prompt.style.清爽实验', '清爽实验', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用清爽实验教学视觉，白色背景、深蓝标题、青绿分区与橙色步骤标记。标题和正文使用清晰黑体气质，器材为简洁写实插画或干净的三维模型，适度表现透明、金属、橡胶等材质。只展示本课实验所需器材、操作和观察对象，按顺序分区，关键部位无遮挡。实验装置、数量与操作由输入决定，不编造实验结果、化学方程式或连接关系。"'::jsonb, '"采用清爽实验教学视觉，白色背景、深蓝标题、青绿分区与橙色步骤标记。标题和正文使用清晰黑体气质，器材为简洁写实插画或干净的三维模型，适度表现透明、金属、橡胶等材质。只展示本课实验所需器材、操作和观察对象，按顺序分区，关键部位无遮挡。实验装置、数量与操作由输入决定，不编造实验结果、化学方程式或连接关系。"'::jsonb, 'string', true),
('image_prompt.style.机制蓝图', '机制蓝图', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用机制蓝图视觉，浅灰蓝背景、深蓝文字、青绿主体线条与橙色关键方向。标题用粗黑体，正文清晰，技术线稿配少量半透明结构和局部放大。依据本课内容画出物体、装置、运动或因果关系，箭头起止与标签明确，网格仅作极淡辅助。深底只用于适合的封面，内容区保持可读；不加入无意义代码、发光线或不存在的结构。"'::jsonb, '"采用机制蓝图视觉，浅灰蓝背景、深蓝文字、青绿主体线条与橙色关键方向。标题用粗黑体，正文清晰，技术线稿配少量半透明结构和局部放大。依据本课内容画出物体、装置、运动或因果关系，箭头起止与标签明确，网格仅作极淡辅助。深底只用于适合的封面，内容区保持可读；不加入无意义代码、发光线或不存在的结构。"'::jsonb, 'string', true),
('image_prompt.style.自然博物', '自然博物', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用自然博物图谱视觉，象牙白纸底、森林绿标题、赭色细节、深灰标注。标题为稳重宋体气质，正文和标签清晰。主体以细致科学插画表现本课指定的植物、动物或自然样本，可用局部放大与观察卡呈现特征，线条与色彩柔和但结构清楚。背景不抢主体，不把不同物种特征拼接，不虚构学名、分类和标本信息。"'::jsonb, '"采用自然博物图谱视觉，象牙白纸底、森林绿标题、赭色细节、深灰标注。标题为稳重宋体气质，正文和标签清晰。主体以细致科学插画表现本课指定的植物、动物或自然样本，可用局部放大与观察卡呈现特征，线条与色彩柔和但结构清楚。背景不抢主体，不把不同物种特征拼接，不虚构学名、分类和标本信息。"'::jsonb, 'string', true),
('image_prompt.style.微观结构', '微观结构', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用微观结构教学视觉，浅蓝白背景、深蓝标题，青绿与紫色区分结构，少量橙色强调变化。文字用清晰黑体，主体为简洁三维剖面或扁平示意，层次清楚、材质适度半透明。按照本课提供的细胞、分子或其他结构组织图像，用颜色和简短标签形成一一对应，不用复杂粒子背景。明确这是教学模型，不为美观改变连接、相对位置和结构数量。"'::jsonb, '"采用微观结构教学视觉，浅蓝白背景、深蓝标题，青绿与紫色区分结构，少量橙色强调变化。文字用清晰黑体，主体为简洁三维剖面或扁平示意，层次清楚、材质适度半透明。按照本课提供的细胞、分子或其他结构组织图像，用颜色和简短标签形成一一对应，不用复杂粒子背景。明确这是教学模型，不为美观改变连接、相对位置和结构数量。"'::jsonb, 'string', true),
('image_prompt.style.地貌景观', '地貌景观', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用地貌与生态景观视觉，沙岩米色、海洋蓝与植被绿构成有限色板，标题深蓝黑体、正文深灰。以本课指定的自然景观摄影气质或清晰地形剖面为主体，用简短标注和少量方向箭头帮助观察，地形与天空层次明确。内容页留出浅底说明区。生成画面只作景观或机制示意，不自动绘制行政边界，不编造等高线、经纬度、比例尺和观测数据。"'::jsonb, '"采用地貌与生态景观视觉，沙岩米色、海洋蓝与植被绿构成有限色板，标题深蓝黑体、正文深灰。以本课指定的自然景观摄影气质或清晰地形剖面为主体，用简短标注和少量方向箭头帮助观察，地形与天空层次明确。内容页留出浅底说明区。生成画面只作景观或机制示意，不自动绘制行政边界，不编造等高线、经纬度、比例尺和观测数据。"'::jsonb, 'string', true),
('image_prompt.style.地球宇宙', '地球宇宙', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用地球与宇宙探索视觉，深靛蓝用于封面，冷白文字、青蓝结构与少量琥珀色强调；内容页使用浅底说明区。标题为稳健粗黑体，主视觉为清楚的天体、地球现象或观测对象，克制的科学三维渲染，光照与空间关系明确。示意图按输入安排位置和方向，非真实比例时标为示意；不添加科幻飞船、任意行星或伪造遥感数据。"'::jsonb, '"采用地球与宇宙探索视觉，深靛蓝用于封面，冷白文字、青蓝结构与少量琥珀色强调；内容页使用浅底说明区。标题为稳健粗黑体，主视觉为清楚的天体、地球现象或观测对象，克制的科学三维渲染，光照与空间关系明确。示意图按输入安排位置和方向，非真实比例时标为示意；不添加科幻飞船、任意行星或伪造遥感数据。"'::jsonb, 'string', true),
('image_prompt.style.数字界面', '数字界面', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用清爽数字界面教学视觉，白底、深蓝标题、青绿节点和少量紫色强调。标题和正文为清晰无衬线字体，规整卡片、流程节点与简单设备插图组成画面，必要代码使用清楚的等宽字气质。只展示本课相关的界面、操作步骤或信息流程，箭头方向与输入一致。不把教学流程画成商业数据看板，不生成无意义代码和复杂霓虹背景。"'::jsonb, '"采用清爽数字界面教学视觉，白底、深蓝标题、青绿节点和少量紫色强调。标题和正文为清晰无衬线字体，规整卡片、流程节点与简单设备插图组成画面，必要代码使用清楚的等宽字气质。只展示本课相关的界面、操作步骤或信息流程，箭头方向与输入一致。不把教学流程画成商业数据看板，不生成无意义代码和复杂霓虹背景。"'::jsonb, 'string', true),
('image_prompt.style.工程模型', '工程模型', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用工程模型教学视觉，浅灰背景、石墨色文字、工程蓝与安全橙区分部件。标题粗黑体，正文清晰；主体为哑光三维模型、结构爆炸图或操作步骤插画，柔和均匀光照。突出本课对象的部件、连接与功能，视角便于观察，非关键细节简化。尺寸和参数只使用提供内容，不制造看似精确的工程标注，不为了视觉效果增加结构。"'::jsonb, '"采用工程模型教学视觉，浅灰背景、石墨色文字、工程蓝与安全橙区分部件。标题粗黑体，正文清晰；主体为哑光三维模型、结构爆炸图或操作步骤插画，柔和均匀光照。突出本课对象的部件、连接与功能，视角便于观察，非关键细节简化。尺寸和参数只使用提供内容，不制造看似精确的工程标注，不为了视觉效果增加结构。"'::jsonb, 'string', true),
('image_prompt.style.节奏音乐', '节奏音乐', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用节奏音乐教学视觉，暖白底、靛蓝与珊瑚色块，标题用清楚圆角黑体，正文深灰。有序重复形状表现节奏感，主体为本课乐器、演奏动作或聆听情境；布局清爽，谱例与节奏标记只按输入绘制，不把随机音符当作准确乐谱。"'::jsonb, '"采用节奏音乐教学视觉，暖白底、靛蓝与珊瑚色块，标题用清楚圆角黑体，正文深灰。有序重复形状表现节奏感，主体为本课乐器、演奏动作或聆听情境；布局清爽，谱例与节奏标记只按输入绘制，不把随机音符当作准确乐谱。"'::jsonb, 'string', true),
('image_prompt.style.古典音乐', '古典音乐', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用雅致古典音乐教学视觉，米灰底、深棕标题与少量平面金色，短标题用稳重衬线字体气质，正文清晰。以本课乐器、演奏场景或作品相关对象为主视觉，线条与留白克制，曲谱和年代只使用提供内容，不自行添加装饰乐谱和作曲家肖像。"'::jsonb, '"采用雅致古典音乐教学视觉，米灰底、深棕标题与少量平面金色，短标题用稳重衬线字体气质，正文清晰。以本课乐器、演奏场景或作品相关对象为主视觉，线条与留白克制，曲谱和年代只使用提供内容，不自行添加装饰乐谱和作曲家肖像。"'::jsonb, 'string', true),
('image_prompt.style.材料拼贴', '材料拼贴', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用材料拼贴教学视觉，暖白底、有限的红黄蓝或本课材料色，标题用粗黑体，正文墨黑。纸张、织物、颜料或本课指定材料呈现真实纹理与轻微投影，构成明确的主体和步骤。允许手工边缘，但信息卡对齐、文字区干净，展示对象与背景分开。不要混用所有艺术媒介，不加入无关贴纸和未经提供的名画碎片。"'::jsonb, '"采用材料拼贴教学视觉，暖白底、有限的红黄蓝或本课材料色，标题用粗黑体，正文墨黑。纸张、织物、颜料或本课指定材料呈现真实纹理与轻微投影，构成明确的主体和步骤。允许手工边缘，但信息卡对齐、文字区干净，展示对象与背景分开。不要混用所有艺术媒介，不加入无关贴纸和未经提供的名画碎片。"'::jsonb, 'string', true),
('image_prompt.style.运动分解', '运动分解', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用清楚的运动分解视觉，白底、海军蓝文字、活力橙步骤与草绿辅助线。标题为粗壮黑体，正文清晰，运动人物以自然人体比例的插画或写实示意呈现。用相同视角的少量顺序画面表现动作，关键肢体位置、运动方向与站位清楚，不用动感模糊遮挡。动作和规则依据输入，背景简洁，不添加竞赛广告、领奖台和无关器材。"'::jsonb, '"采用清楚的运动分解视觉，白底、海军蓝文字、活力橙步骤与草绿辅助线。标题为粗壮黑体，正文清晰，运动人物以自然人体比例的插画或写实示意呈现。用相同视角的少量顺序画面表现动作，关键肢体位置、运动方向与站位清楚，不用动感模糊遮挡。动作和规则依据输入，背景简洁，不添加竞赛广告、领奖台和无关器材。"'::jsonb, 'string', true),
('image_prompt.style.温暖陪伴', '温暖陪伴', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用温暖陪伴视觉，奶油白底、低饱和鼠尾草绿、杏粉与浅蓝，深灰文字。标题用亲切端正的圆角黑体，正文易读；人物使用温和手绘插画，表情自然，在本课相关的校园、家庭或交流情境中互动。保留观察、表达与记录空间，颜色柔和但文字对比清楚。避免污名化标签、恐怖脑部意象和把单一表情当作心理诊断。"'::jsonb, '"采用温暖陪伴视觉，奶油白底、低饱和鼠尾草绿、杏粉与浅蓝，深灰文字。标题用亲切端正的圆角黑体，正文易读；人物使用温和手绘插画，表情自然，在本课相关的校园、家庭或交流情境中互动。保留观察、表达与记录空间，颜色柔和但文字对比清楚。避免污名化标签、恐怖脑部意象和把单一表情当作心理诊断。"'::jsonb, 'string', true),
('image_prompt.style.探究手账', '探究手账', '独立生图与图片 PPT 共用。修改后用于后续新生成的图片与整套风格设定。', 'image_prompts', '"采用项目探究手账视觉，米白纸底、深灰文字、青绿与橙色步骤标记。标题用清晰黑体或克制手写字气质，正文端正。照片、工具、材料、观察记录和任务卡按本课真实任务组织，用轻微纸纹、少量胶带边和简洁连线形成记录感。顺序和结果空间清楚，学习单保留填写区；不自动填入测量数据、实验答案、结论或项目成果。"'::jsonb, '"采用项目探究手账视觉，米白纸底、深灰文字、青绿与橙色步骤标记。标题用清晰黑体或克制手写字气质，正文端正。照片、工具、材料、观察记录和任务卡按本课真实任务组织，用轻微纸纹、少量胶带边和简洁连线形成记录感。顺序和结果空间清楚，学习单保留填写区；不自动填入测量数据、实验答案、结论或项目成果。"'::jsonb, 'string', true),
('image_prompt.ppt.outline', '文字大纲输入模板', '与 Work Skill 中的“大纲阶段”指令一起发给文本模型。', 'image_prompts', '"根据以下输入生成课件文字大纲。\n学科：{{subject}}\n年级：{{grade}}\n用户补充需求：{{requirements}}\n教学流程：\n{{flow}}"'::jsonb, '"根据以下输入生成课件文字大纲。\n学科：{{subject}}\n年级：{{grade}}\n用户补充需求：{{requirements}}\n教学流程：\n{{flow}}"'::jsonb, 'string', true),
('image_prompt.ppt.feedback', '大纲追改模板', '用户提出大纲修改意见时追加。', 'image_prompts', '"\n本轮修改意见：{{feedback}}\n当前编辑的完整大纲：\n{{outline}}"'::jsonb, '"\n本轮修改意见：{{feedback}}\n当前编辑的完整大纲：\n{{outline}}"'::jsonb, 'string', true),
('image_prompt.ppt.settings', '共用设定输入模板', '与 Work Skill 中的“共用设定阶段”指令一起发给文本模型。', 'image_prompts', '"根据已选风格与确认大纲确定整套共用设定。\n现有风格提示词：{{style_prompt}}\n已确认课程信息：{{course}}\n已确认大纲：{{outline}}"'::jsonb, '"根据已选风格与确认大纲确定整套共用设定。\n现有风格提示词：{{style_prompt}}\n已确认课程信息：{{course}}\n已确认大纲：{{outline}}"'::jsonb, 'string', true),
('image_prompt.ppt.page', '逐页出图总模板', '将已确认大纲和整套设定组装为每页出图要求，再进入生图总模板。', 'image_prompts', '"生成一张完整16:9课堂PPT页面，页面序号{{page_number}}/{{total}}。艺术风格只使用请求中已有的风格要求。\n整套共用设定（字体、参考字号、位置、HEX色号、课程信息必须沿用，不重新设计）：\n{{settings}}\n本页标题：{{title}}\n{{page_content}}\n导航使用“{{navigation}}”，页码使用“{{page_number}} / {{total}}”。封面可显示完整单元、课题与已提供教师信息，正文仅保留简洁导航；没有提供的课程信息省略。字号按统一画布参考保持视觉层级，正文过多时清楚分区，不删字。不要画PPT软件界面、水印、占位文字或额外课程名称。"'::jsonb, '"生成一张完整16:9课堂PPT页面，页面序号{{page_number}}/{{total}}。艺术风格只使用请求中已有的风格要求。\n整套共用设定（字体、参考字号、位置、HEX色号、课程信息必须沿用，不重新设计）：\n{{settings}}\n本页标题：{{title}}\n{{page_content}}\n导航使用“{{navigation}}”，页码使用“{{page_number}} / {{total}}”。封面可显示完整单元、课题与已提供教师信息，正文仅保留简洁导航；没有提供的课程信息省略。字号按统一画布参考保持视觉层级，正文过多时清楚分区，不删字。不要画PPT软件界面、水印、占位文字或额外课程名称。"'::jsonb, 'string', true),
('image_prompt.ppt.markdown_page', '完整页面说明执行规则', '采用 Markdown 页面说明的大纲，使用此模板传入每页内容。', 'image_prompts', '"本页已确认的完整页面说明：\n{{content_markdown}}\n按本页说明区分学生实际看到的文字、配图与排版建议。投屏文字逐字保留；配图／排版说明及教学环节标签用于执行，不作为文字印到页面上。允许只有标题或图像为主的页面，不补凑正文。不增加答案、材料或额外栏目。"'::jsonb, '"本页已确认的完整页面说明：\n{{content_markdown}}\n按本页说明区分学生实际看到的文字、配图与排版建议。投屏文字逐字保留；配图／排版说明及教学环节标签用于执行，不作为文字印到页面上。允许只有标题或图像为主的页面，不补凑正文。不增加答案、材料或额外栏目。"'::jsonb, 'string', true),
('image_prompt.ppt.legacy_page', '结构化页面执行规则', '兼容历史结构化大纲的逐页出图。', 'image_prompts', '"本页学生投屏文字（逐字保留，不改写，不增加答案或虚构材料）：\n{{text}}\n本页配图内容：{{image_description}}\n参考排版：{{layout}}\n所属教学环节：{{section}}"'::jsonb, '"本页学生投屏文字（逐字保留，不改写，不增加答案或虚构材料）：\n{{text}}\n本页配图内容：{{image_description}}\n参考排版：{{layout}}\n所属教学环节：{{section}}"'::jsonb, 'string', true),
('image_prompt.ppt.default_image', '缺少配图说明时的要求', '历史大纲没有单独配图说明时使用。', 'image_prompts', '"根据文字内容组织页面，不添加无关插图。"'::jsonb, '"根据文字内容组织页面，不添加无关插图。"'::jsonb, 'string', true),
('image_prompt.ppt.default_layout', '缺少排版说明时的要求', '历史大纲没有单独排版说明时使用。', 'image_prompts', '"根据内容灵活构图，沿用整套标题和导航位置。"'::jsonb, '"根据内容灵活构图，沿用整套标题和导航位置。"'::jsonb, 'string', true),
('image_prompt.courseware.style', '整套配图风格模板', '使用课件视觉方案中的画风、色板、光线等信息。', 'image_prompts', '"统一画风：{{illustration_style}}；统一色板：{{palette}}；统一光线：{{lighting}}；统一质感：{{texture}}；写实程度：{{realism}}；统一视觉语言：清晰线条、适度留白、教育展示友好"'::jsonb, '"统一画风：{{illustration_style}}；统一色板：{{palette}}；统一光线：{{lighting}}；统一质感：{{texture}}；写实程度：{{realism}}；统一视觉语言：清晰线条、适度留白、教育展示友好"'::jsonb, 'string', true),
('image_prompt.courseware.background', '课件背景图模板', 'V2 图文课件，以及没有专属整页提示词的页面使用。', 'image_prompts', '"为《{{title}}》这同一份教学PPT生成第{{page_number}}页“{{slide_title}}”的{{role}}图片。\n{{style}}\n本页画面需求：{{description}}。\n16:9 全景背景图，整页铺满PPT画布；主体和主要视觉重心根据本页文字排版需要避开文字密集区，保留可读的文字安全区；不要生成窄幅插图、边框装饰或独立素材，不要在图片中绘制标题。\n图片放置规则：统一作为整页 background，使用 cover 铺满 16:9 画布；文字层由PPT原生组件独立叠放。\n整套图片保持同一美术系统：色调、媒介、线条、光线、质感和写实程度一致；每页的具体人物、景物、物体与场景只由本页需求决定，不继承封面或其他页面的具体意象，不把单个案例扩展为整节课的固定主视觉。\n16:9 横版，适合课堂投影。画面内严禁出现文字、字母、数字、标志、logo、水印、界面截图或边框外内容。"'::jsonb, '"为《{{title}}》这同一份教学PPT生成第{{page_number}}页“{{slide_title}}”的{{role}}图片。\n{{style}}\n本页画面需求：{{description}}。\n16:9 全景背景图，整页铺满PPT画布；主体和主要视觉重心根据本页文字排版需要避开文字密集区，保留可读的文字安全区；不要生成窄幅插图、边框装饰或独立素材，不要在图片中绘制标题。\n图片放置规则：统一作为整页 background，使用 cover 铺满 16:9 画布；文字层由PPT原生组件独立叠放。\n整套图片保持同一美术系统：色调、媒介、线条、光线、质感和写实程度一致；每页的具体人物、景物、物体与场景只由本页需求决定，不继承封面或其他页面的具体意象，不把单个案例扩展为整节课的固定主视觉。\n16:9 横版，适合课堂投影。画面内严禁出现文字、字母、数字、标志、logo、水印、界面截图或边框外内容。"'::jsonb, 'string', true),
('image_prompt.courseware.generated_page', '模型生成的整页提示词模板', 'V3 纯图片课件：页面提示词本身由 AI 课件 Skill 生成，此处可维护统一追加或包装规则。', 'image_prompts', '"{{image_prompt}}"'::jsonb, '"{{image_prompt}}"'::jsonb, 'string', true),
('image_prompt.courseware.visual_design', '整体视觉设计指令', '旧版纯图片课件确认大纲后，生成供用户确认的整体视觉设计。', 'image_prompts', '"你是 HAI 纯图片PPT的整套视觉总监。根据已经确认的 PPT 大纲，只输出一段给用户确认的“整体视觉设计”，不要生成逐页提示词、不要生成图片提示词、不要复述逐页文字、不要输出 JSON。\n\n这一段必须明确说清：整体气质与适用学段、主色/辅助色/背景色及对比关系、写实/插画/卡通/抽象等图片艺术风格、人物与场景的统一程度、光线与质感、中文字体与标题/正文层级、16:9 画面的构图和投影可读性。不得把某一页的具体人物、景物或物体当成整套固定意象。长度控制在 180—600 个中文字，用一至两个自然段表达。\n\n课程：{{subject}}，{{grade}}，{{topic}}\n已确认大纲：\n{{outline}}"'::jsonb, '"你是 HAI 纯图片PPT的整套视觉总监。根据已经确认的 PPT 大纲，只输出一段给用户确认的“整体视觉设计”，不要生成逐页提示词、不要生成图片提示词、不要复述逐页文字、不要输出 JSON。\n\n这一段必须明确说清：整体气质与适用学段、主色/辅助色/背景色及对比关系、写实/插画/卡通/抽象等图片艺术风格、人物与场景的统一程度、光线与质感、中文字体与标题/正文层级、16:9 画面的构图和投影可读性。不得把某一页的具体人物、景物或物体当成整套固定意象。长度控制在 180—600 个中文字，用一至两个自然段表达。\n\n课程：{{subject}}，{{grade}}，{{topic}}\n已确认大纲：\n{{outline}}"'::jsonb, 'string', true),
('image_prompt.courseware.image_planning', '逐页生图提示词设计指令', '旧版纯图片课件把确认大纲转换为逐页生图提示词时使用。输出结构须保持兼容。', 'image_prompts', '"你是 HAI 纯图片PPT的逐页生图提示词设计器。下面的逐页内容稿已经确定教学顺序和全部学生可见素材。你的任务不是重新写课件，而是把每一页转换成一个可直接交给图片 API 的、可执行的中文生图提示词。\n\n输出且只能输出 JSON：{\"schemaVersion\":\"hai_courseware_image_prompts_v1\",\"visualProfile\":{\"illustrationStyle\":\"统一媒介与风格\",\"palette\":[\"颜色\"],\"lighting\":\"统一光线\",\"texture\":\"统一质感\",\"realismLevel\":\"统一写实程度\",\"visualKeywords\":[\"风格关键词\"]},\"pages\":[{\"pageId\":\"P01\",\"prompt\":\"完整的逐页生图提示词\",\"negativePrompt\":\"禁止项\",\"visibleText\":[\"必须在图片中原样排版的学生可见文字\"]}]}\n\n严格规则：\n1. pages 必须与内容稿页数完全一致，按 P01、P02……顺序输出，不能遗漏、合并或新增页面。\n2. 每页 prompt 必须明确：16:9 横版、1K、教育投影场景、页面构图、视觉重心、层级、留白和文字安全区；同一套课件必须严格执行用户已确认的整体视觉设计并使用同一 visualProfile，但每页的具体场景只由本页内容决定。\n3. 纯图片PPT中没有可编辑文字层，因此 prompt 必须要求图片自身排版本页全部学生可见文字。visibleText 必须从本页 title 和 materials 原样提取，不能改写、缩写、翻译、补充答案或遗漏题干、条件、选项、步骤、数据和结论。教师备注、来源摘录中的教师说明不得放进图片。\n4. 中文文字要使用清晰的现代无衬线字体，标题与正文有明确字号层级，文字放在安全区内，避免与主体重叠；如果文字很多，要通过卡片、分栏、流程、时间线或信息层级排版，而不是删字或用小到不可读的字。\n5. 图片应是完整的一页课件画面，而不是背景素材、照片、海报模板或局部插图；不要生成 PPT 软件界面、边框外内容、logo、水印、随机字母、乱码或虚构事实。negativePrompt 写清楚这些禁止项。\n6. prompt 中可以复述 visibleText，且必须把要渲染的文字用【页面文字】区块列出并标明“逐字保留”。不要只写‘根据内容生成’或‘见大纲’。\n\n课程：{{subject}}，{{grade}}，{{topic}}；页数档位：{{length}}；画面比例：16:9；分辨率：1K\n用户已确认的整体视觉设计：\n{{visual_design}}\n\n逐页内容稿：\n{{outline}}"'::jsonb, '"你是 HAI 纯图片PPT的逐页生图提示词设计器。下面的逐页内容稿已经确定教学顺序和全部学生可见素材。你的任务不是重新写课件，而是把每一页转换成一个可直接交给图片 API 的、可执行的中文生图提示词。\n\n输出且只能输出 JSON：{\"schemaVersion\":\"hai_courseware_image_prompts_v1\",\"visualProfile\":{\"illustrationStyle\":\"统一媒介与风格\",\"palette\":[\"颜色\"],\"lighting\":\"统一光线\",\"texture\":\"统一质感\",\"realismLevel\":\"统一写实程度\",\"visualKeywords\":[\"风格关键词\"]},\"pages\":[{\"pageId\":\"P01\",\"prompt\":\"完整的逐页生图提示词\",\"negativePrompt\":\"禁止项\",\"visibleText\":[\"必须在图片中原样排版的学生可见文字\"]}]}\n\n严格规则：\n1. pages 必须与内容稿页数完全一致，按 P01、P02……顺序输出，不能遗漏、合并或新增页面。\n2. 每页 prompt 必须明确：16:9 横版、1K、教育投影场景、页面构图、视觉重心、层级、留白和文字安全区；同一套课件必须严格执行用户已确认的整体视觉设计并使用同一 visualProfile，但每页的具体场景只由本页内容决定。\n3. 纯图片PPT中没有可编辑文字层，因此 prompt 必须要求图片自身排版本页全部学生可见文字。visibleText 必须从本页 title 和 materials 原样提取，不能改写、缩写、翻译、补充答案或遗漏题干、条件、选项、步骤、数据和结论。教师备注、来源摘录中的教师说明不得放进图片。\n4. 中文文字要使用清晰的现代无衬线字体，标题与正文有明确字号层级，文字放在安全区内，避免与主体重叠；如果文字很多，要通过卡片、分栏、流程、时间线或信息层级排版，而不是删字或用小到不可读的字。\n5. 图片应是完整的一页课件画面，而不是背景素材、照片、海报模板或局部插图；不要生成 PPT 软件界面、边框外内容、logo、水印、随机字母、乱码或虚构事实。negativePrompt 写清楚这些禁止项。\n6. prompt 中可以复述 visibleText，且必须把要渲染的文字用【页面文字】区块列出并标明“逐字保留”。不要只写‘根据内容生成’或‘见大纲’。\n\n课程：{{subject}}，{{grade}}，{{topic}}；页数档位：{{length}}；画面比例：16:9；分辨率：1K\n用户已确认的整体视觉设计：\n{{visual_design}}\n\n逐页内容稿：\n{{outline}}"'::jsonb, 'string', true),
('image_prompt.courseware.outline_rule', '纯图片大纲补充规则', '旧版课件大纲阶段对纯图片页面文字与画面需求的补充要求。', 'image_prompts', '"纯图片PPT规则：每页最终只有一张 16:9 图片，图片本身必须承载本页学生要看的标题、正文、题目、材料、选项、步骤、数据和结论；所有学生可见文字必须逐字出现在 materials 中，不能只写‘见教案’。imageDescription 必须描述本页场景、构图、视觉层级、文字安全区和适合图片内排版的留白；不要写教师备注。后续阶段会把本页完整材料转换为生图提示词。"'::jsonb, '"纯图片PPT规则：每页最终只有一张 16:9 图片，图片本身必须承载本页学生要看的标题、正文、题目、材料、选项、步骤、数据和结论；所有学生可见文字必须逐字出现在 materials 中，不能只写‘见教案’。imageDescription 必须描述本页场景、构图、视觉层级、文字安全区和适合图片内排版的留白；不要写教师备注。后续阶段会把本页完整材料转换为生图提示词。"'::jsonb, 'string', true),
('image_prompt.courseware.default_visual', '未提供视觉设定时的默认要求', '旧版纯图片课件未提供整体视觉设计时使用。', 'image_prompts', '"使用适合学科和学段的统一现代教育视觉风格。"'::jsonb, '"使用适合学科和学段的统一现代教育视觉风格。"'::jsonb, 'string', true),
('image_prompt.courseware.visual_system', '整体视觉设计角色指令', '旧版纯图片课件视觉设计阶段的系统角色提示词。', 'image_prompts', '"你只为已确认的纯图片PPT大纲制定一套可供用户确认的整体视觉设计。"'::jsonb, '"你只为已确认的纯图片PPT大纲制定一套可供用户确认的整体视觉设计。"'::jsonb, 'string', true),
('image_prompt.courseware.planning_system', '逐页提示词角色指令', '旧版纯图片课件逐页生图规划阶段的系统角色提示词。', 'image_prompts', '"你只依据已确认大纲和整体视觉设计生成内部逐页生图参数，必须保留全部学生可见文字。"'::jsonb, '"你只依据已确认大纲和整体视觉设计生成内部逐页生图参数，必须保留全部学生可见文字。"'::jsonb, 'string', true)
